244:    @Override
245:    public void registerListener(int propId, float rate, ICarPropertyEventListener listener)
246:            throws IllegalArgumentException {
247:        if (DBG) {
248:            Slogf.d(TAG, "registerListener: propId=0x" + toHexString(propId) + " rate=" + rate);
249:        }
250:        if (listener == null) {
251:            Slogf.e(TAG, "registerListener: Listener is null.");
252:            throw new IllegalArgumentException("listener cannot be null.");
253:        }
254:
255:        IBinder listenerBinder = listener.asBinder();
256:        CarPropertyConfig propertyConfig;
257:        Client finalClient;
258:        synchronized (mLock) {
259:            propertyConfig = mConfigs.get(propId);
260:            if (propertyConfig == null) {
261:                // Do not attempt to register an invalid propId
262:                Slogf.e(TAG, "registerListener:  propId is not in config list: 0x"
263:                        + toHexString(propId));
264:                return;
265:            }
266:            CarServiceUtils.assertPermission(mContext, mHal.getReadPermission(propId));
267:            // Get or create the client for this listener
268:            Client client = mClientMap.get(listenerBinder);
269:            if (client == null) {
270:                client = new Client(listener);
271:                if (client.isDead()) {
272:                    Slogf.w(TAG, "the ICarPropertyEventListener is already dead");
273:                    return;
274:                }
275:                mClientMap.put(listenerBinder, client);
276:            }
277:            client.addProperty(propId, rate);
278:            // Insert the client into the propId --> clients map
279:            List<Client> clients = mPropIdClientMap.get(propId);
280:            if (clients == null) {
281:                clients = new ArrayList<Client>();
282:                mPropIdClientMap.put(propId, clients);
283:            }
284:            if (!clients.contains(client)) {
285:                clients.add(client);
286:            }
287:            // Set the new rate
288:            if (rate > mHal.getSampleRate(propId)) {
289:                mHal.subscribeProperty(propId, rate);
290:            }
291:            finalClient = client;
292:        }
293:
294:        // propertyConfig and client are NonNull.
295:        mHandler.post(() ->
296:                getAndDispatchPropertyInitValue(propertyConfig, finalClient));
297:    }
