299:    private void getAndDispatchPropertyInitValue(CarPropertyConfig config, Client client) {
300:        List<CarPropertyEvent> events = new ArrayList<>();
301:        int propId = config.getPropertyId();
302:        if (config.isGlobalProperty()) {
303:            CarPropertyValue value = mHal.getPropertySafe(propId, 0);
304:            if (value != null) {
305:                CarPropertyEvent event = new CarPropertyEvent(
306:                        CarPropertyEvent.PROPERTY_EVENT_PROPERTY_CHANGE, value);
307:                events.add(event);
308:            }
309:        } else {
310:            for (int areaId : config.getAreaIds()) {
311:                CarPropertyValue value = mHal.getPropertySafe(propId, areaId);
312:                if (value != null) {
313:                    CarPropertyEvent event = new CarPropertyEvent(
314:                            CarPropertyEvent.PROPERTY_EVENT_PROPERTY_CHANGE, value);
315:                    events.add(event);
316:                }
317:            }
318:        }
319:        if (events.isEmpty()) {
320:            return;
321:        }
322:        try {
323:            client.onEvent(events);
324:        } catch (RemoteException ex) {
325:            // If we cannot send a record, its likely the connection snapped. Let the binder
326:            // death handle the situation.
327:            Slogf.e(TAG, "onEvent calling failed", ex);
328:        }
329:    }
