346:    @GuardedBy("mLock")
347:    private void unregisterListenerBinderLocked(int propId, IBinder listenerBinder) {
348:        float updateMaxRate = 0f;
349:        Client client = mClientMap.get(listenerBinder);
350:        List<Client> propertyClients = mPropIdClientMap.get(propId);
351:        if (mConfigs.get(propId) == null) {
352:            // Do not attempt to unregister an invalid propId
353:            Slogf.e(TAG, "unregisterListener: propId is not in config list:0x%s",
354:                    toHexString(propId));
355:            return;
356:        }
357:        if ((client == null) || (propertyClients == null)) {
358:            Slogf.e(TAG, "unregisterListenerBinderLocked: Listener was not previously "
359:                    + "registered.");
360:            return;
361:        }
362:        if (propertyClients.remove(client)) {
363:            int propLeft = client.removeProperty(propId);
364:            if (propLeft == 0) {
365:                mClientMap.remove(listenerBinder);
366:            }
367:            clearSetOperationRecorderLocked(propId, client);
368:
369:        } else {
370:            Slogf.e(TAG, "unregisterListenerBinderLocked: Listener was not registered for "
371:                    + "propId=0x" + toHexString(propId));
372:            return;
373:        }
374:
375:        if (propertyClients.isEmpty()) {
376:            // Last listener for this property unsubscribed.  Clean up
377:            mPropIdClientMap.remove(propId);
378:            mSetOperationClientMap.remove(propId);
379:            mHal.unsubscribeProperty(propId);
380:            return;
381:        }
382:        // Other listeners are still subscribed.  Calculate the new rate
383:        for (int i = 0; i < propertyClients.size(); i++) {
384:            Client c = propertyClients.get(i);
385:            float rate = c.getRate(propId);
386:            updateMaxRate = Math.max(rate, updateMaxRate);
387:        }
388:        if (Float.compare(updateMaxRate, mHal.getSampleRate(propId)) != 0) {
389:            try {
390:                // Only reset the sample rate if needed
391:                mHal.subscribeProperty(propId, updateMaxRate);
392:            } catch (IllegalArgumentException e) {
393:                Slogf.e(TAG, "failed to subscribe to propId=0x" + toHexString(propId)
394:                        + ", error: " + e);
395:            }
396:        }
397:    }
