428:     * @return the list of properties' configs that the caller may access.
429:     */
430:    @NonNull
431:    @Override
432:    public List<CarPropertyConfig> getPropertyConfigList(int[] propIds) {
433:        // Cache the granted permissions
434:        Set<String> grantedPermission = new HashSet<>();
435:        List<CarPropertyConfig> availableProp = new ArrayList<>();
436:        if (propIds == null) {
437:            return availableProp;
438:        }
439:        for (int propId : propIds) {
440:            String readPermission = getReadPermission(propId);
441:            String writePermission = getWritePermission(propId);
442:            if (readPermission == null && writePermission == null) {
443:                continue;
444:            }
445:            // Check if context already granted permission first
446:            if (checkAndUpdateGrantedPermissionSet(mContext, grantedPermission, readPermission)
447:                    || checkAndUpdateGrantedPermissionSet(mContext, grantedPermission,
448:                    writePermission)) {
449:                synchronized (mLock) {
450:                    availableProp.add(mConfigs.get(propId));
451:                }
452:            }
453:        }
454:        if (DBG) {
455:            Slogf.d(TAG, "getPropertyList returns " + availableProp.size() + " configs");
456:        }
457:        return availableProp;
458:    }
